s:ui-execute-js.script:
function cmVal(id) {
	var host = document.getElementById(id);
	if(!host) { throw new Error(id + ' missing'); }
	var cmEl = host.querySelector('.CodeMirror');
	if(!cmEl || !cmEl.CodeMirror) { throw new Error(id + ' CodeMirror not ready'); }
	return cmEl.CodeMirror.getValue();
}
return {
	json: cmVal('jsonContent-lang-editor'),
	xml: cmVal('xmlContent-lang-editor'),
	schema: cmVal('jsonSchemaContent-lang-editor')
};

var host = document.getElementById('jsonContent-lang-editor');
var cmEl = host.querySelector('.CodeMirror');
cmEl.CodeMirror.setValue('{ not valid json');
return true;

var errEl = document.getElementById('language-demo-error');
var errText = (errEl && errEl.textContent) ? errEl.textContent.trim() : '';
var feedback = document.querySelector('#jsonContent .invalid-feedback');
var feedbackText = (feedback && feedback.textContent) ? feedback.textContent.trim() : '';
var combined = errText + ' ' + feedbackText;
var hasResponse = !!document.getElementById('language-demo-response');
return !hasResponse && (combined.indexOf('Invalid') >= 0 || combined.indexOf('Validation') >= 0);
